"""Generate public documentation and local history from the bilingual content source."""
from pathlib import Path
import json
r=Path(__file__).resolve().parents[1]; c=json.loads((r/'resources/content.json').read_text())
for folder in ['docs','wiki']:(r/folder).mkdir(exist_ok=True)
for lang,d in c.items():
 de=lang=='de';faq='\n\n'.join('### '+q+'\n\n'+a for q,a in d['faq']);history='\n\n'.join('### '+v+' · '+date+'\n\n'+'\n'.join('- **'+p+':** '+t for p,t in items) for v,date,items in d['history'])
 names=['Auf einen Blick','Installation','Gezielte Bereinigung','Voraussetzungen und Grenzen','Häufige Fragen','Änderungsverlauf','Autor und Projekt','Meldungen und Unterstützung'] if de else ['At a glance','Installation','Targeted cleanup','Requirements and limits','Frequently asked questions','Changelog','Author and project','Reporting and support']
 import unicodedata,re
 anchor=lambda s:re.sub(r'[^\w -]','',s.lower()).replace(' ','-')
 text='# Purify WPForms Lite\n\n![Purify WPForms Lite](assets/github-banner-' + lang + '.png)\n\n## '+('Kurzvorstellung' if de else 'About')+'\n\n'+d['intro']+'\n\nVersion **1.1.0** · WordPress **6.7+** · PHP **8.0+** · GPL v2 or later\n\n'+('[English](README.md)' if de else '[Deutsch](README.de.md)')+' · [FAQ](docs/FAQ.'+lang+'.md)\n\n'+('## Inhaltsverzeichnis' if de else '## Contents')+'\n\n'+' · '.join('['+x+'](#'+anchor(x)+')' for x in names)+'\n\n## '+names[0]+'\n\n'+'\n'.join('- '+x for x in d['glance'])+'\n\n## '+names[1]+'\n\n'
 text+=('1. Installiere das ZIP unter Plugins → Installieren → Plugin hochladen.\n2. Aktiviere WPForms Lite und Purify. Prüfe den Status in der Pluginliste.\n3. Alternativ importiere genau eine passende Snippet-JSON. Plugin und Snippet nicht parallel aktivieren.' if de else '1. Install the ZIP under Plugins → Add New → Upload Plugin.\n2. Activate WPForms Lite and Purify. Check the status on the Plugins page.\n3. Alternatively import one matching snippet JSON. Do not activate the plugin and a duplicate snippet together.')
 text+='\n\n## '+names[2]+'\n\n'+('Entfernt bekannte Werbemenüs, den Upgrade-Link in der Toolbar, Pro-Vorlagen und benannte Premium-Werbebereiche. Formulare, kostenlose Felder, Zahlungen, Sicherungen, Einstellungen und notwendige Hinweise bleiben erhalten. Eintrags- und Gutschein-Upsells, Checkliste, fremde Pluginwerbung und unnötige Dashboardkarten werden gezielt entfernt. Die Bereinigung verändert keine gespeicherten WPForms-Daten.' if de else 'Removes known promotional menus, the toolbar upgrade link, Pro templates and named premium promotion areas. Forms, free fields, payments, backups, settings and operational notices remain. Entry and coupon upsells, checklist navigation, cross-plugin promotion and unnecessary dashboard cards are removed selectively. Cleanup does not modify saved WPForms data.')
 text+='\n\n## '+names[3]+'\n\n'+('PHP 8.0 ist gegenüber 1.0.0 neu erforderlich. WordPress 6.7 bleibt die Mindestversion. Eingebettet: Library 0.8.1 und Updater 2.1.0. Andere WPForms-Versionen werden vorsichtig ausgelassen. ClassicPress und echte GitHub-Updatezustellung dieses unveröffentlichten Standes sind nicht bestätigt. Banner und Icons verwenden eine eigenständige Formulargrafik.' if de else 'PHP 8.0 is newly required compared with 1.0.0. WordPress 6.7 remains the minimum. Embedded components: Library 0.8.1 and Updater 2.1.0. Other WPForms releases are skipped conservatively. ClassicPress and real GitHub update delivery of this unpublished build are not verified. Banners and icons use an original form illustration.')
 text+='\n\n## '+names[4]+'\n\n'+faq+'\n\n['+('Vollständige Fragen nach Themen' if de else 'Full FAQ by topic')+'](docs/FAQ.'+lang+'.md)\n\n## '+names[5]+'\n\n'+history+'\n\n## '+names[6]+'\n\nDavid Decker – DECKERWEB. '+('Purify konzentriert sich auf die kostenlose WPForms-Oberfläche. Vertrieb über GitHub; keine WordPress.org-Veröffentlichung.' if de else 'Purify focuses on the free WPForms interface. Distribution through GitHub; no WordPress.org release.')+'\n\n## '+names[7]+'\n\n[Issues](https://github.com/deckerweb/purify-wpforms-lite/issues) · [Security](SECURITY.md)\n\n[Ko-fi](https://ko-fi.com/deckerweb) · [Buy Me a Coffee](https://buymeacoffee.com/daveshine) · [PayPal](https://paypal.me/deckerweb) · [Newsletter](https://eepurl.com/gbAUUn)\n\nCopyright © 2022–2026 David Decker – DECKERWEB. GPL-2.0-or-later. [Third-party origins](THIRD-PARTY.md).\n'
 (r/('README.de.md' if de else 'README.md')).write_text(text)
 title='Fragen nach Themen' if de else 'FAQ by topic';ft='# '+title+'\n\n'+('[English](FAQ.en.md)' if de else '[Deutsch](FAQ.de.md)')+'\n\n## '+('Einstieg und Alltag' if de else 'Getting started and daily use')+'\n\n'+'\n\n'.join('### '+q+'\n\n'+a for q,a in d['faq'][:5])+'\n\n## '+('Technische Fragen' if de else 'Technical questions')+'\n\n'+'\n\n'.join('### '+q+'\n\n'+a for q,a in d['faq'][5:])+'\n'
 (r/'docs'/('FAQ.'+lang+'.md')).write_text(ft);(r/'wiki'/('Fragen-nach-Themen.md' if de else 'FAQ-by-topic.md')).write_text(ft.replace('FAQ.en.md','FAQ-by-topic.md').replace('FAQ.de.md','Fragen-nach-Themen.md'))
 (r/'wiki'/('Home-de.md' if de else 'Home.md')).write_text(text.replace('(README.md)', '(Home)').replace('(README.de.md)', '(Home-de)').replace('(assets/','(https://raw.githubusercontent.com/deckerweb/purify-wpforms-lite/main/assets/').replace('(docs/FAQ.'+lang+'.md)','('+('Fragen-nach-Themen' if de else 'FAQ-by-topic')+')'))
 (r/'docs'/('CHANGELOG.'+lang+'.md')).write_text('# '+names[5]+'\n\n'+history+'\n')
(r/'wiki/_Sidebar.md').write_text('[Home](Home) · [Deutsch](Home-de)\n\n- [FAQ by topic](FAQ-by-topic)\n- [Fragen nach Themen](Fragen-nach-Themen)\n')
d=c['en'];(r/'readme.txt').write_text('=== Purify WPForms Lite ===\nContributors: deckerweb\nTags: forms, wpforms, cleanup, purify\nRequires at least: 6.7\nTested up to: 7.1.3\nRequires PHP: 8.0\nStable tag: 1.1.0\nLicense: GPLv2 or later\nLicense URI: https://www.gnu.org/licenses/gpl-2.0.html\n\n'+d['intro']+'\n\n== Description ==\n\n'+'\n'.join('* '+x for x in d['glance'])+'\n\n== Installation ==\n\nUpload the plugin ZIP, activate WPForms Lite and Purify, and check the Plugins-page status.\n\n== Frequently Asked Questions ==\n\n'+'\n\n'.join('= '+q+' =\n\n'+a for q,a in d['faq'])+'\n\nFull FAQ: https://github.com/deckerweb/purify-wpforms-lite/wiki/FAQ-by-topic\n\n== Changelog ==\n\n'+'\n\n'.join('= '+v+' · '+date+' =\n\n'+'\n'.join('* '+p+': '+t for p,t in items) for v,date,items in d['history'])+'\n')
parts=[]
for v,date,items in c['en']['history']:
 parts.append(json.dumps('= '+v+' · ',ensure_ascii=False)+" . __( "+json.dumps(date)+", 'purify-wpforms-lite' ) . \" =\\n\"")
 for p,t in items:parts.append("'* ' . __( "+json.dumps(p)+", 'purify-wpforms-lite' ) . ': ' . __( "+json.dumps(t)+", 'purify-wpforms-lite' ) . \"\\n\"")
(r/'includes/history.php').write_text("<?php\n/** Localized categorized history generated from the shared content source. */\nif ( ! defined( 'ABSPATH' ) ) { exit; }\nreturn "+' .\n'.join(parts)+';\n')
